package com.nexustools.genericui.resources

import com.nexustools.genericui.image.ImageBuffer
import com.nexustools.genericui.image.ImageDecodeOptions
import com.nexustools.genericui.io.ByteBuffer
import com.nexustools.genericui.io.Readable
import com.nexustools.genericui.res.DrawableResource
import com.nexustools.genericui.style.color.RgbaColor
import com.nexustools.genericui.style.css.PrecompiledStyleSheet

/**
 * Typed Android-like resource handle (`R.drawable.ic_brush`, `R.string.app_name`, `RC.drawable.ic_move`, etc.)
 * generated by the GenericUI Gradle plugin (`compileGenericUiResources`) and resolved at runtime via [ResourceResolver].
 *
 * - [id]: Android-style `0x7fTTNNNN` numeric resource ID (also mapped to Win32 `.rc` resource IDs).
 * - [type]: The [ResourceType] category (`DRAWABLE`, `STRING`, `COLOR`, `DIMEN`, `RAW`, `FONT`, etc.).
 * - [name]: Snake-case resource identifier (e.g. `"ic_tool_brush"`, `"app_title"`).
 * - [relativePath]: Original relative path inside the project's resources directory.
 */
data class ResourceID(
    val id: Int,
    val type: ResourceType,
    val name: String,
    val relativePath: String = ""
) {
    /**
     * Canonical URI (`"res://drawable/ic_tool_brush"`) understood by all GenericUI native backends.
     */
    fun toResourceUri(): String = "res://${type.directoryName}/$name"

    /**
     * Win32 `.rc` integer resource ID (`1000 + (id and 0xFFFF)`).
     */
    val win32ResourceId: Int
        get() = ((type.typeCode and 0x0F) * 1000) + (id and 0x0FFF)

    /** Resolves this [ResourceID] as a localized/formatted string via [ResourceResolver.getString]. */
    fun getString(vararg formatArgs: Any): String =
        ResourceResolver.getString(this, *formatArgs)

    /** Resolves this [ResourceID] as an [RgbaColor] via [ResourceResolver.getColor]. */
    fun getColor(): RgbaColor =
        ResourceResolver.getColor(this)

    /** Resolves this [ResourceID] as a pixel dimension (`Float`) via [ResourceResolver.getDimenPx]. */
    fun getDimenPx(): Float =
        ResourceResolver.getDimenPx(this)

    /** Resolves this [ResourceID] as an integer resource via [ResourceResolver.getInteger]. */
    fun getInteger(): Int =
        ResourceResolver.getInteger(this)

    /** Resolves this [ResourceID] as a boolean resource via [ResourceResolver.getBool]. */
    fun getBool(): Boolean =
        ResourceResolver.getBool(this)

    /** Resolves this [ResourceID] to a backend-appropriate URL or resource URI via [ResourceResolver.getUrl]. */
    fun getUrl(): String =
        ResourceResolver.getUrl(this)

    /** Resolves this [ResourceID] to raw binary bytes via [ResourceResolver.getBytes]. */
    fun getBytes(): ByteArray? =
        ResourceResolver.getBytes(this)

    /** Resolves this [ResourceID] to a [ByteBuffer] via [ResourceResolver.getBuffer]. */
    fun getBuffer(): ByteBuffer? =
        ResourceResolver.getBuffer(this)

    /** Asynchronously opens a non-blocking [Readable] stream for this [ResourceID] via [ResourceResolver.openReadable]. */
    suspend fun openReadable(): Readable? =
        ResourceResolver.openReadable(this)

    /** Asynchronously opens a non-blocking [Readable] stream for this [ResourceID] via [ResourceResolver.openReadable]. */
    suspend fun openStream(): Readable? =
        ResourceResolver.openReadable(this)

    /** Decodes this [ResourceID] into an [ImageBuffer] via [ResourceResolver.getImageBuffer]. */
    fun getImageBuffer(options: ImageDecodeOptions = ImageDecodeOptions()): ImageBuffer? =
        ResourceResolver.getImageBuffer(this, options)

    /** Resolves this [ResourceID] as a [DrawableResource] via [ResourceResolver.getDrawable]. */
    fun getDrawable(): DrawableResource? =
        ResourceResolver.getDrawable(this)

    /** Resolves this [ResourceID] as a [PrecompiledStyleSheet] via [ResourceResolver.getStyleSheet]. */
    fun getStyleSheet(): PrecompiledStyleSheet? =
        ResourceResolver.getStyleSheet(this)

    override fun toString(): String = toResourceUri()
}
